            type: "workflow.step.end",
            runId,
            data: {
              parentWorkflow,
              workflowId,
              runId,
              executionPath,
              resumeSteps,
              stepResults,
              prevResult: stepResult,
              activeStepsPath,
              requestContext,
              state: currentState,
              outputOptions
            }
