// backend/api/import.ts
init_schema();
await init_db();
import { and as and7, eq as eq8 } from "drizzle-orm";
var import_adm_zip = __toESM(require_adm_zip());
import { join as join7 } from "path";
import { mkdirSync as mkdirSync3, readdirSync, readFileSync as readFileSync2, rmSync, statSync as statSync2 } from "fs";
var WRAPPER_NAME = "Imported";
var WRAPPER_DESC = "Auto-created from ZIP import";
var decodeFileName = (buf) => {
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(buf);
  } catch {
    return new TextDecoder("gbk").decode(buf);
  }
};
var importZip = async (c) => {
  const uid = Number(c.get("uid"));
  const formData = await c.req.formData();
  const notebookId = Number(formData.get("notebook_id"));
  const file = formData.get("file");
  if (!notebookId || isNaN(notebookId)) {
    return c.json({ code: -1000, msg: "import.notebook_required", data: null });
  }
  if (!file || !(file instanceof File)) {
    return c.json({ code: -1000, msg: "import.file_required", data: null });
  }
  const owned = await checkNotebookOwnership(notebookId, uid);
  if (!owned) {
    return c.json({ code: -1000, msg: "import.notebook_not_found", data: null });
  }
  const tmpDir = join7("/tmp", `zest_import_${uid}_${Date.now()}`);
  mkdirSync3(tmpDir, { recursive: true });
  try {
    const zipPath = join7(tmpDir, "import.zip");
    await Bun.write(zipPath, file);
    const zip = new import_adm_zip.default(zipPath, {
      decoder: {
        efs: true,
        decode: decodeFileName,
        encode: (data) => Buffer.from(data, "utf8")
      }
    });
    const extractDir = join7(tmpDir, "extracted");
    zip.extractAllTo(extractDir, true);
    const hasMdDirectly = (dir) => readdirSync(dir).some((name) => {
      try {
        return name.endsWith(".md") && statSync2(join7(dir, name)).isFile();
      } catch {
        return false;
      }
    });
    const entries = readdirSync(extractDir);
    const topDirs = entries.filter((e) => {
      try {
        return statSync2(join7(extractDir, e)).isDirectory();
      } catch {
        return false;
      }
    });
    const topMds = entries.filter((e) => {
      try {
        return e.endsWith(".md") && statSync2(join7(extractDir, e)).isFile();
      } catch {
        return false;
      }
    });
    let rootDir = extractDir;
    if (topDirs.length === 1 && topMds.length === 0) {
      if (!hasMdDirectly(join7(extractDir, topDirs[0]))) {
        rootDir = join7(extractDir, topDirs[0]);
      }
    }
    await db.transaction(async (tx) => {
      const pending = [];
      const getOrCreateWrapper = async (parentDbId, fallbackMtime) => {
        const existing = await tx.select({ id: notebooks.id }).from(notebooks).where(and7(eq8(notebooks.user_id, uid), eq8(notebooks.parent_id, parentDbId), eq8(notebooks.title, WRAPPER_NAME))).get();
        if (existing)
          return existing.id;
        const [nb] = await tx.insert(notebooks).values({
          user_id: uid,
          parent_id: parentDbId,
          title: WRAPPER_NAME,
          description: WRAPPER_DESC,
          sort_order: 0,
          created_at: fallbackMtime,
          updated_at: fallbackMtime
        }).returning();
        return nb.id;
      };
      let effectiveParent = notebookId;
      if (hasMdDirectly(rootDir)) {
        effectiveParent = await getOrCreateWrapper(notebookId, new Date);
      }
      async function importDir(dir, parentDbId) {
        const items = readdirSync(dir);
        for (const name of items) {
          const fullPath = join7(dir, name);
          let st;
          try {
            st = statSync2(fullPath);
          } catch {
            continue;
          }
          if (st.isDirectory()) {
            const existing = await tx.select({ id: notebooks.id }).from(notebooks).where(and7(eq8(notebooks.user_id, uid), eq8(notebooks.parent_id, parentDbId), eq8(notebooks.title, name))).get();
            const childId = existing ? existing.id : (await tx.insert(notebooks).values({
              user_id: uid,
              parent_id: parentDbId,
              title: name,
              description: "",
              sort_order: 0,
              created_at: st.mtime,
              updated_at: st.mtime
            }).returning())[0].id;
            await importDir(fullPath, childId);
          }
        }
        for (const name of items) {
          const fullPath = join7(dir, name);
          let st;
          try {
            st = statSync2(fullPath);
          } catch {
            continue;
          }
          if (st.isFile() && name.endsWith(".md")) {
            const title = name.replace(/\.md$/, "");
            const dup = await tx.select({ id: notes.id }).from(notes).where(and7(eq8(notes.user_id, uid), eq8(notes.notebook_id, parentDbId), eq8(notes.title, title), eq8(notes.is_deleted, 0))).get();
            if (dup)
              continue;
            const content = readFileSync2(fullPath, "utf-8");
            pending.push({
              notebookId: parentDbId,
              title,
              content,
              mtime: st.mtime
            });
          }
        }
      }
      await importDir(rootDir, effectiveParent);
      if (pending.length > 0) {
        await tx.insert(notes).values(pending.map((e) => ({
          user_id: uid,
          notebook_id: e.notebookId,
          title: e.title,
          content: e.content,
          is_pinned: 0,
          is_deleted: 0,
          sort_order: 0,
          created_at: e.mtime,
          updated_at: e.mtime
        })));
      }
    });
    return c.json({ code: 200, msg: "import.success", data: null });
  } finally {
    try {
      rmSync(tmpDir, { recursive: true, force: true });
    } catch {}
  }
};

// backend/api/export.ts
init_schema();
await init_db();
var import_adm_zip2 = __toESM(require_adm_zip());
import { join as join8 } from "path";
import { mkdirSync as mkdirSync4, writeFileSync, rmSync as rmSync2, utimesSync } from "fs";
import { eq as eq9, and as and8, inArray as inArray3 } from "drizzle-orm";
function sanitizeFilename(name) {
  return name.replace(/[\\/:*?"<>|]/g, "_");
}
function truncateFilename(name, maxLength = 200) {
  if (name.length <= maxLength)
    return name;
  return name.slice(0, maxLength);
}
async function getAllChildNotebookIds(parentId) {
  const children = await db.select({ id: notebooks.id }).from(notebooks).where(eq9(notebooks.parent_id, parentId));
  let ids = children.map((c) => c.id);
  for (const child of children) {
    const childIds = await getAllChildNotebookIds(child.id);
    ids = ids.concat(childIds);
  }
  return ids;
}
function buildNotebookPath(notebookId, notebookMap) {
  const nb = notebookMap.get(notebookId);
  if (!nb)
    return "";
  if (!nb.parent_id || !notebookMap.has(nb.parent_id)) {
    return sanitizeFilename(nb.title);
  }
  const parentPath = buildNotebookPath(nb.parent_id, notebookMap);
  return join8(parentPath, sanitizeFilename(nb.title));
}
var exportZip = async (c) => {
  const uid = Number(c.get("uid"));
  const notebookId = Number(c.req.query("notebook_id"));
  if (!notebookId || isNaN(notebookId)) {
    return c.json({ code: -1000, msg: "export.notebook_required", data: null });
  }
  const owned = await checkNotebookOwnership(notebookId, uid);
  if (!owned) {
    return c.json({ code: -1000, msg: "export.notebook_not_found", data: null });
  }
  const rootNotebook = await db.select().from(notebooks).where(eq9(notebooks.id, notebookId)).get();
  if (!rootNotebook) {
    return c.json({ code: -1000, msg: "export.notebook_not_found", data: null });
  }
  const allNotebookIds = [notebookId, ...await getAllChildNotebookIds(notebookId)];
  const notes2 = await db.select({
    id: notes.id,
    notebook_id: notes.notebook_id,
    title: notes.title,
    content: notes.content,
    created_at: notes.created_at,
    updated_at: notes.updated_at
  }).from(notes).where(and8(inArray3(notes.notebook_id, allNotebookIds), eq9(notes.is_deleted, 0)));
  if (notes2.length === 0) {
    return c.json({ code: -1000, msg: "export.no_notes", data: null });
  }
  if (notes2.length > 1000) {
    return c.json({ code: -1000, msg: "export.too_many_notes", data: null });
  }
  const allNotebooks = await db.select({
    id: notebooks.id,
    parent_id: notebooks.parent_id,
    title: notebooks.title
  }).from(notebooks).where(inArray3(notebooks.id, allNotebookIds));
  const notebookMap = new Map(allNotebooks.map((nb) => [nb.id, nb]));
  const tmpDir = join8("/tmp", `zest_export_${uid}_${Date.now()}`);
  const rootDir = join8(tmpDir, sanitizeFilename(rootNotebook.title));
  mkdirSync4(rootDir, { recursive: true });
  try {
    const createdFiles = new Map;
    for (const note of notes2) {
      const notebookPath = buildNotebookPath(note.notebook_id, notebookMap);
      const fullDirPath = join8(tmpDir, notebookPath);
      mkdirSync4(fullDirPath, { recursive: true });
      let baseName = truncateFilename(sanitizeFilename(note.title));
      let fileName = `${baseName}.md`;
      let filePath = join8(fullDirPath, fileName);
      if (createdFiles.has(filePath)) {
        fileName = `${baseName}_${randomString(3)}.md`;
        filePath = join8(fullDirPath, fileName);
      }
      createdFiles.set(filePath, 1);
      writeFileSync(filePath, note.content, "utf-8");
      const createdAt = new Date(note.created_at);
      const updatedAt = new Date(note.updated_at);
      utimesSync(filePath, createdAt, updatedAt);
    }
    const zip = new import_adm_zip2.default;
    zip.addLocalFolder(tmpDir);
    const zipBuffer = zip.toBuffer();
    c.header("Content-Type", "application/zip");
    c.header("Content-Disposition", `attachment; filename*=UTF-8''${encodeURIComponent(rootNotebook.title)}.zip`);
    return c.body(zipBuffer);
  } finally {
    try {
      rmSync2(tmpDir, { recursive: true, force: true });
    } catch {}
  }
};

