var uploadFiles = async (c) => {
  const uid = Number(c.get("uid"));
  const formData = await c.req.formData();
  const fileList = formData.getAll("file[]");
  if (!fileList || fileList.length === 0) {
    return c.json({ code: -1000, msg: "file.upload.no_file", data: null });
  }
  const results = [];
  for (const item of fileList) {
    if (!(item instanceof File))
      continue;
    if (!ALLOWED_IMAGE_TYPES.includes(item.type)) {
      return c.json({ code: -1000, msg: "file.upload.invalid_type", data: null });
    }
    if (item.size > MAX_FILE_SIZE) {
      return c.json({ code: -1000, msg: "file.upload.too_large", data: null });
    }
    const fileId = "zn-" + randomString(8);
    let ext = getExtFromName(item.name);
    if (!ext)
      ext = getExtFromMime(item.type);
    const now = new Date;
    const year = String(now.getFullYear());
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const relativePath = join9("images", String(uid), year, month, `${fileId}.${ext}`);
    const fullPath = join9(FILES_BASE_PATH, relativePath);
    const dir = fullPath.substring(0, fullPath.lastIndexOf("/"));
    if (!existsSync5(dir)) {
      mkdirSync5(dir, { recursive: true });
    }
    await Bun.write(fullPath, item);
    await db.insert(files).values({
      file_id: fileId,
      user_id: uid,
      original_name: item.name,
      file_path: relativePath,
      file_size: item.size,
      mime_type: item.type,
      created_at: now
    }).run();
    results.push({
      file_id: fileId,
      original_name: item.name,
      url: `/files/${relativePath}`
    });
  }
  return c.json({
    code: 200,
    msg: "file.upload.success",
    data: results
  });
};

// backend/api/search.ts
await init_db();
import { sql as sql4 } from "drizzle-orm";
var searchNotes = async (c) => {
  const uid = Number(c.get("uid"));
  const notebookId = Number(c.req.query("notebook_id"));
  const keyword = (c.req.query("keyword") || "").trim();
  if (!notebookId || isNaN(notebookId)) {
    return c.json({
      code: -1000,
      msg: "search.notebook_required",
      data: null
    });
  }
  if (!keyword || keyword.length < 2) {
    return c.json({
      code: -1000,
      msg: "search.keyword_too_short",
      data: null
    });
  }
  const notebookExists = await checkNotebookOwnership(notebookId, uid);
  if (!notebookExists) {
    return c.json({
      code: -1000,
      msg: "search.notebook_not_found",
      data: null
    });
  }
  const categoryTreeCte = sql4`
        WITH RECURSIVE category_tree(id) AS (
            SELECT id FROM notebooks WHERE id = ${notebookId} AND user_id = ${uid}
            UNION ALL
            SELECT n.id FROM notebooks n
            JOIN category_tree ct ON n.parent_id = ct.id
            WHERE n.user_id = ${uid}
        )
    `;
  let results;
  if (keyword.length < 3) {
    const likePattern = `%${keyword.replace(/[%_\\]/g, "\\$&")}%`;
    results = await db.all(sql4`
            ${categoryTreeCte}
            SELECT n.id, n.notebook_id, n.title, n.content, n.is_pinned, n.sort_order, n.created_at, n.updated_at
            FROM notes n
            WHERE n.user_id = ${uid}
              AND n.is_deleted = 0
              AND n.notebook_id IN (SELECT id FROM category_tree)
              AND (n.title LIKE ${likePattern} ESCAPE '\\' OR n.content LIKE ${likePattern} ESCAPE '\\')
            ORDER BY n.is_pinned DESC, n.updated_at DESC
            LIMIT 50;
        `);
  } else {
    const escapedKeyword = `"${keyword.replace(/"/g, '""')}"`;
    results = await db.all(sql4`
            ${categoryTreeCte}
            SELECT n.id, n.notebook_id, n.title, n.content, n.is_pinned, n.sort_order, n.created_at, n.updated_at
            FROM notes n
            JOIN notes_fts f ON n.id = f.rowid
            WHERE n.user_id = ${uid}
              AND n.is_deleted = 0
              AND n.notebook_id IN (SELECT id FROM category_tree)
              AND notes_fts MATCH ${escapedKeyword}
            ORDER BY rank
            LIMIT 50;
        `);
  }
  return c.json({
    code: 200,
    msg: "search.success",
    data: results
  });
};

// backend/api/ai.ts
init_schema();
init_dist14();
init_dist16();
init_request_context();
await __promiseAll([
  init_db(),
  init_vector2()
]);
import { desc as desc5, eq as eq10, and as and9, inArray as inArray5, sql as sql5 } from "drizzle-orm";
await init_ai_config();
async function vectorizeNextBatch(batchSize = 20) {
  const embeddingConfig = await getAIEmbeddingConfig();
  if (!embeddingConfig?.enabled) {
    return { success: 0, skipped: 0, failed: 0 };
  }
  const notes2 = await db.select().from(notes).where(and9(eq10(notes.is_deleted, 0), eq10(notes.allow_vectorize, 1), eq10(notes.is_vectorized, 0))).orderBy(desc5(notes.id)).limit(batchSize);
  if (notes2.length === 0) {
    return { success: 0, skipped: 0, failed: 0 };
  }
  const maxContentLength = getMaxContentLength(embeddingConfig.model);
  const tooLong = [];
  const toProcess = [];
  for (const note of notes2) {
    if (note.content.length > maxContentLength) {
      tooLong.push(note.id);
    } else {
      toProcess.push(note);
    }
  }
  if (tooLong.length > 0) {
    await db.update(notes).set({ is_vectorized: 2, vectorized_at: new Date }).where(inArray5(notes.id, tooLong));
  }
  if (toProcess.length === 0) {
    return { success: 0, skipped: tooLong.length, failed: 0 };
  }
  const userIds = [...new Set(toProcess.map((n) => n.user_id))];
  const allNotebooks = await db.select({
    id: notebooks.id,
    parent_id: notebooks.parent_id,
    user_id: notebooks.user_id
  }).from(notebooks).where(inArray5(notebooks.user_id, userIds));
  const notebookParentMap = new Map;
  for (const nb of allNotebooks) {
    notebookParentMap.set(nb.id, nb.parent_id);
  }
  const getRootNotebookId = (notebookId) => {
    const visited = new Set;
    let current = notebookId;
    while (true) {
      if (visited.has(current))
        break;
      visited.add(current);
      const parentId = notebookParentMap.get(current);
      if (parentId === null)
        return current;
      if (parentId === undefined)
        return notebookId;
      current = parentId;
    }
    return notebookId;
  };
  const noteRootMap = new Map;
  for (const note of toProcess) {
    noteRootMap.set(note.id, getRootNotebookId(note.notebook_id));
  }
  let successIds = [];
  let failedIds = [];
  try {
    const openai = createOpenAI3({
      baseURL: getBaseURL(embeddingConfig.provider),
      apiKey: embeddingConfig.api_key
    });
    const contents = toProcess.map((n) => `${n.title}

${n.content}`);
    const isBgeModel = embeddingConfig.model.toLowerCase().includes("bge");
    const { embeddings } = await embedMany({
      model: openai.embedding(embeddingConfig.model),
      values: contents,
      providerOptions: isBgeModel ? undefined : { openai: { dimensions: VECTOR_DIMENSIONS } }
    });
    if (embeddings.length > 0) {
      await vectorStore.upsert({
        indexName: INDEX_NAME,
        vectors: embeddings,
        metadata: toProcess.map((note) => ({
          note_id: note.id,
          user_id: note.user_id,
          notebook_id: noteRootMap.get(note.id),
          title: note.title
        }))
      });
    }
    successIds = toProcess.map((n) => n.id);
    console.log(`Vectorization complete: ${successIds.length} succeeded, ${tooLong.length} skipped, ${failedIds.length} failed`);
  } catch (err) {
    console.error("Vectorization failed:", err);
    failedIds = toProcess.map((n) => n.id);
  }
  if (successIds.length > 0) {
    await db.update(notes).set({ is_vectorized: 1, vectorized_at: new Date }).where(inArray5(notes.id, successIds));
  }
  if (failedIds.length > 0) {
    await db.update(notes).set({ is_vectorized: 3, vectorized_at: new Date }).where(inArray5(notes.id, failedIds));
  }
  return {
    success: successIds.length,
    skipped: tooLong.length,
    failed: failedIds.length
  };
}
