var getPublicDocLlmsTxt = async (c) => {
  const slug = c.req.param("slug");
  const doc = await db.select().from(docs).where(eq11(docs.slug, slug)).get();
  if (!doc || doc.status !== "active") {
    return c.text("Not Found", 404);
  }
  const rootNotebook = await db.select({ title: notebooks.title, description: notebooks.description }).from(notebooks).where(eq11(notebooks.id, doc.notebook_id)).get();
  const notebookIds = await collectSubtreeIds(doc.notebook_id);
  const idList = [...notebookIds];
  const notebooks2 = await db.select({
    id: notebooks.id,
    parent_id: notebooks.parent_id,
    title: notebooks.title,
    sort_order: notebooks.sort_order
  }).from(notebooks).where(inArray6(notebooks.id, idList)).orderBy(asc2(notebooks.sort_order)).all();
  const notes2 = await db.select({
    id: notes.id,
    notebook_id: notes.notebook_id,
    title: notes.title,
    is_pinned: notes.is_pinned,
    sort_order: notes.sort_order,
    created_at: notes.created_at
  }).from(notes).where(and10(inArray6(notes.notebook_id, idList), eq11(notes.is_deleted, 0))).orderBy(desc6(notes.is_pinned), asc2(notes.sort_order), desc6(notes.created_at)).all();
  const notebooksById = new Map(notebooks2.map((nb) => [nb.id, nb]));
  const sectionTitle = (nb) => {
    if (nb.parent_id === null)
      return nb.title;
    const parent = notebooksById.get(nb.parent_id);
    if (!parent || parent.parent_id === null)
      return nb.title;
    return `${parent.title}/${nb.title}`;
  };
  const grouped = new Map;
  for (const note of notes2) {
    const list = grouped.get(note.notebook_id) || [];
    list.push(note);
    grouped.set(note.notebook_id, list);
  }
  const escapeMd = (s) => s.replace(/[\[\]()]/g, (ch) => `\\${ch}`).replace(/\s+/g, " ").trim();
  const origin = new URL(c.req.url).origin;
  const title = escapeMd(doc.title || rootNotebook?.title || "");
  const description = escapeMd(doc.description || rootNotebook?.description || "");
  const lines = [`# ${title}`];
  if (description)
    lines.push("", `> ${description}`);
  for (const nb of notebooks2) {
    const list = grouped.get(nb.id);
    if (!list || list.length === 0)
      continue;
    lines.push("", `## ${escapeMd(sectionTitle(nb))}`);
    for (const note of list) {
      lines.push(`- [${escapeMd(note.title)}](${origin}/note/${note.id}.md)`);
    }
  }
  return c.text(lines.join(`
`) + `
`, 200, {
    "Content-Type": "text/plain; charset=utf-8"
  });
};

