var verifyApiToken = async (token, c, role = "user") => {
  if (!token || token.length < 32) {
    return false;
  }
  try {
    const session = await db.select().from(sessions).where(and11(eq12(sessions.token, token), eq12(sessions.status, "active"))).get();
    if (!session) {
      return false;
    }
    if (session.expires_at.getTime() <= Date.now()) {
      await db.update(sessions).set({ status: "expired" }).where(eq12(sessions.id, session.id)).run();
      return false;
    }
    if (role === "admin" && session.role !== "admin") {
      return false;
    }
    const user = await db.select({
      id: users.id,
      username: users.username
    }).from(users).where(and11(eq12(users.id, session.uid), eq12(users.status, "active"))).get();
    if (!user) {
      return false;
    }
    c.set("uid", user.id);
    c.set("role", session.role);
    c.set("username", user.username);
    c.set("token", token);
    return true;
  } catch {
    return false;
  }
};

